import json, os, statistics
BASE = "bench/results/2026-10-12/m1-ngram/replay"
arms = ["off-greedy","A-greedy","B-greedy","off-prod","A-prod"]
phases = ["single-agent","single-mem","dual-agent","dual-mem"]
def load(a):
    return [json.loads(l) for l in open(f"{BASE}/{a}/requests.jsonl") if l.strip()]
data = {a: load(a) for a in arms}
def tok_s(rows):
    ms = sum((r.get("predicted_ms") or 0) for r in rows)
    n = sum((r.get("predicted_n") or 0) for r in rows)
    return 1000*n/ms if ms else float('nan')
def med(rows):
    per = [(r.get("predicted_n") or 0)/r["predicted_ms"]*1000 for r in rows if r.get("predicted_ms")]
    return statistics.median(per) if per else float('nan')
print(f"{'arm':12} {'phase':12} {'n':3} {'tok/s':6} {'med':6} {'tcjson':7} {'same-off':6}")
for a in arms:
    for ph in phases:
        fg = [r for r in data[a] if r["phase"]==ph and r["fg_bg"]=="fg"]
        if not fg: continue
        print(f"{a:12} {ph:12} {len(fg):3} {tok_s(fg):6.1f} {med(fg):6.1f} {sum(r['tool_call_json_valid'] for r in fg)/len(fg):7.3f} n")
EOF

