import json, statistics
BASE = "bench/results/2026-10-12/m1-ngram/replay"
arms = ["off-greedy","A-greedy","B-greedy","off-prod","A-prod"]
phases = ["single-agent","single-mem","dual-agent","dual-mem"]
def load(a):
    return [json.loads(l) for l in open(f"{BASE}/{a}/requests.jsonl") if l.strip()]
data = {a: load(a) for a in arms}
def byphase(a,ph):
    return {r["id"]:r for r in data[a] if r["phase"]==ph and r["fg_bg"]=="fg"}

print("=== IDENTITY (greedy) A & B vs off-greedy, same phase+id ===")
for ph in phases:
    off = byphase("off-greedy",ph)
    for a in ["A-greedy","B-greedy"]:
        d = byphase(a,ph)
        n = len(off)
        same = sum(1 for i,r in d.items() if i in off and r.get("out_sha256")==off[i].get("out_sha256"))
        print(f"  {a} {ph}: {same}/{n} = {100*same/n:.1f}%")

print("\n=== CONTROL: off dual vs off single (same id) ===")
# agent ids in single-agent & dual-agent
for phs in [("single-agent","dual-agent","agent"),("single-mem","dual-mem","mem")]:
    sph,dph,role = phs
    s = {r["id"]:r for r in data["off-greedy"] if r["phase"]==sph and r["fg_bg"]=="fg"}
    d = {r["id"]:r for r in data["off-greedy"] if r["phase"]==dph and r["fg_bg"]=="fg"}
    ids = set(s)&set(d)
    same = sum(1 for i in ids if s[i].get("out_sha256")==d[i].get("out_sha256"))
    print(f"  {role}: off {dph} vs {sph} same id: {same}/{len(ids)} = {100*same/len(ids):.1f}%")

print("\n=== RULE checks for A-prod vs off-prod ===")
def tok_s(rows):
    ms=sum((r.get("predicted_ms") or 0) for r in rows); n=sum((r.get("predicted_n") or 0) for r in rows)
    return 1000*n/ms if ms else float('nan')
ap = {ph:{r["id"]:r for r in data["A-prod"] if r["phase"]==ph and r["fg_bg"]=="fg"} for ph in phases}
op = {ph:{r["id"]:r for r in data["off-prod"] if r["phase"]==ph and r["fg_bg"]=="fg"} for ph in phases}
ap_rows = {ph:[r for r in data["A-prod"] if r["phase"]==ph and r["fg_bg"]=="fg"] for ph in phases}
op_rows = {ph:[r for r in data["off-prod"] if r["phase"]==ph and r["fg_bg"]=="fg"] for ph in phases}
print("Rule2 dual-agent prod: A=%.1f off=%.1f ratio=%.3f (need>=1.10)" % (tok_s(ap_rows["dual-agent"]),tok_s(op_rows["dual-agent"]), tok_s(ap_rows["dual-agent"])/tok_s(op_rows["dual-agent"])))
for ph in ["single-agent","single-mem","dual-mem"]:
    a,o = tok_s(ap_rows[ph]),tok_s(op_rows[ph]); r=a/o
    print(f"Rule3 {ph} prod: A={a:.1f} off={o:.1f} ratio={r:.3f} (need>=0.97) {'PASS' if r>=0.97 else 'FAIL'}")
# Rule5 overall tcjson
Aall=[r for r in data["A-prod"] if r["fg_bg"]=="fg"]; oall=[r for r in data["off-prod"] if r["fg_bg"]=="fg"]
print(f"Rule5 overall tcjson: A={sum(r['tool_call_json_valid'] for r in Aall)/len(Aall):.3f} off={sum(r['tool_call_json_valid'] for r in oall)/len(oall):.3f} {'PASS' if sum(r['tool_call_json_valid'] for r in Aall)/len(Aall)>=sum(r['tool_call_json_valid'] for r in oall)/len(oall) else 'FAIL'}")
EOF

